class Solution:
    def validStrings(self, n: int) -> list[str]:
        ans = []
        def dfs(path):
            if len(path) == n:
                ans.append("".join(path))
                return
            path.append('1')
            dfs(path)
            path.pop()
            if not path or path[-1] == '1':
                path.append('0')
                dfs(path)
                path.pop()
        dfs([])
        return ans

class Solution {
public:
    vector<string> validStrings(int n) {
        vector<string> ans;
        string cur = "";
        auto dfs = [&](auto& self) -> void {
            if ((int)cur.size() == n) {
                ans.push_back(cur);
                return;
            }
            cur.push_back('1');
            self(self);
            cur.pop_back();
            if (cur.empty() || cur.back() == '1') {
                cur.push_back('0');
                self(self);
                cur.pop_back();
            }
        };
        dfs(dfs);
        return ans;
    }
};

class Solution {
    private void dfs(StringBuilder sb, int n, List<String> ans) {
        if (sb.length() == n) {
            ans.add(sb.toString());
            return;
        }
        sb.append('1');
        dfs(sb, n, ans);
        sb.deleteCharAt(sb.length() - 1);
        if (sb.length() == 0 || sb.charAt(sb.length() - 1) == '1') {
            sb.append('0');
            dfs(sb, n, ans);
            sb.deleteCharAt(sb.length() - 1);
        }
    }
    public List<String> validStrings(int n) {
        List<String> ans = new ArrayList<>();
        dfs(new StringBuilder(), n, ans);
        return ans;
    }
}

